\begin{theorem}
		\label{thm:conv_proposed_unconstrained_sc_noflag}
		Suppose that $\|\nabla f(y_0)\|> \varepsilon$. For any $\varepsilon>0$, $\mu_0\ge \mu$ and $M_0\le 4L$, Algorithm~\ref{alg:proposed_SCAR_noflag} terminates with $\|\nabla f(\hat x)\|\le\varepsilon$. The total number of gradient evaluations is bounded by  $(4+8\sqrt{5}C_1)\lceil\log_4(\mu_0/\mu)\rceil\sqrt{L/\mu}  + (4+8\sqrt{5}C_1)\sqrt{L/\mu}\lceil\log_2(\|\nabla f(y_0)\|/\varepsilon)\rceil$
		.
		\cmo{
		Moreover, if we have $\mu_0\le 2^{j}\varepsilon/\|y_0-x^*\|$ for some integer $j$, an alternative bound of gradient evaluations is $(4+8\sqrt{5}C_1)\lceil\log_4(\mu_0/\mu)\rceil\sqrt{L/\mu}  +(4+C_1\sqrt{10L/\mu})\max\{1,j\}$.}
	\end{theorem}

