proof.raw_tex:
Specifically, 
noting the $L$-Lipschitz continuity of $\nabla f(x)$ and using the optimality condition $\nabla f_s(x_s^*)=\nabla f(x_s^*) + \sigma_s(x_s^* - \xu_s) = 0$ at $x_s^*$,
we have
\begin{align}
	\label{eq:xs_norm_bound_unconstrained}
	\begin{aligned}
		& \|\nabla f(x_s)\| = \|\nabla f(x_s) - \nabla f(x_s^*) - \sigma_s(x_s^* - \xu_s)\| 
		\\
		\le \ & \|\nabla f(x_s) - \nabla f(x_s^*)\| + \sigma_s\|x_s^* - \xu_s\| 
		\\
		\le\ &  L\|x_s - x_s^*\| + \sigma_s\|x_s^* - \xu_s\|.
	\end{aligned}
\end{align}
We will show later that with the increasing regularization parameter $\sigma_s$ and convex combination design of prox-center in \eqref{eq:xus_unconstrained}, the distance $\sigma_s\|x_s^* - \xu_s\|$ can be further bounded:
\begin{align}
	\label{eq:claim_on_distance_unconstrained}
	\sigma_s\|x_s^* - \xu_s\| \le \sigma_1\|x^* - x_0\| + \sum_{i=2}^s(\sigma_{i-1} + \sigma_i)\|x_{i-1}^* - x_{i-1}\|.
\end{align}
Therefore, $\|\nabla f(x_s)\|$ can be controled by
\begin{align}
	\label{eq:gradS_estimate_unconstrained}
	\|\nabla f(x_s)\| \le\ &  L\|x_s - x_s^*\| + \sigma_1\|x^* - x_0\| + \sum_{i=2}^s(\sigma_{i-1} + \sigma_i)\|x_{i-1}^* - x_{i-1}\|.
\end{align}
Note that the right-hand-side of the above estimate is the summation of terms of form $\|x_i - x_i^*\|$, i.e., the distance from an approximate solution $x_i$ to the optimal solution $x_i^*$ of the $i$-th strongly convex subproblem.
By studying the convergence properties of subroutine $\cA$ for minimizing smooth and strongly convex functions in subproblem \eqref{eq:subproblem_unconstrained}, we will then bound the total number of gradient evaluations needed to reduce the right-hand-side of the above estimate to the accuracy $\varepsilon$. 


\begin{proposition}
	\label{pro:xstar_dist_shrink_unconstrained}
	In  Algorithm~\ref{alg:proposed_unconstrained} we have for all $s\ge 1$ 
	\begin{align}
		\label{eq:dist_subproblem_unconstrained}
		& \|x_{s-1} - x_s^*\|\le \|x_{s-1} - x_{s-1}^*\|, 
		\\
		\label{eq:dist_xu_xstarsig_unconstrained}
		&\sigma_s\|\xu_s - x_s^*\| 
		\le \sum_{i=1}^{s}(\sigma_{i-1} + \sigma_{i})\|x_{i-1}^* - x_{i-1}\|
		.
	\end{align}
\end{proposition}

\begin{proof}
	With the selection of $\gamma_s = 1 - \sigma_{s-1}/\sigma_s$ in the definition of prox-center $\xu_s$ in   \eqref{eq:xus_unconstrained}, the subproblem \eqref{eq:subproblem_unconstrained} is equivalent to
	\begin{align*}
		x_s^* = \argmin_{x\in \R^n} f(x) + \dfrac{\sigma_{s-1}}{2}\|x - \xu_{s-1}\|^2 + \dfrac{\sigma_s - \sigma_{s-1}}{2}\|x - x_{s-1}\|^2,\ \forall s \ge 1.
	\end{align*}
	Noting the optimality of $x_{s-1}^*$ in \eqref{eq:subproblem_unconstrained}  and $x_s^*$ in the above subproblem we have
	\begin{align*}
		& f(x_{s-1}^*) + \dfrac{\sigma_{s-1}}{2}\|x_{s-1}^* - \xu_{s-1}\|^2 + \dfrac{\sigma_s - \sigma_{s-1}}{2}\|x_s^* - x_{s-1}\|^2
		\\
		\le\ & f(x_s^*) + \dfrac{\sigma_{s-1}}{2}\|x_s^* - \xu_{s-1}\|^2 + \dfrac{\sigma_s - \sigma_{s-1}}{2}\|x_s^* - x_{s-1}\|^2 
		\\
		\le\ & f(x_{s-1}^*) + \dfrac{\sigma_{s-1}}{2}\|x_{s-1}^* - \xu_{s-1}\|^2 + \dfrac{\sigma_s - \sigma_{s-1}}{2}\|x_{s-1}^* - x_{s-1}\|^2.
	\end{align*}
	The conclusion in \eqref{eq:dist_subproblem_unconstrained} then follows from the above relation and the assumption $\sigma_s>\sigma_{s-1}$ required by Algorithm~\ref{alg:proposed_unconstrained}.

	We move to prove the next result \eqref{eq:dist_xu_xstarsig_unconstrained}. Denoting $\alpha_s:=\sigma_s - \sigma_{s-1}$ for all $s$ and noting that $\gamma_s = \alpha_s/\sigma_s$ in \eqref{eq:xus_unconstrained}, we can rewrite the definition of $\xu_s$ in \eqref{eq:xus_unconstrained} to
	$
	\sigma_s \xu_s = \sigma_{s-1}\xu_{s-1} + \alpha_s x_{s-1}.
	$
	Recalling that $\sigma_0=0$, the above recursive relation yields
	$
	\sigma_s\xu_s = \sum_{i=1}^{s}\alpha_ix_{i-1}.
	$
	In other words, $\xu_s$ is a convex combination of $x_0,\ldots, x_{s-1}$ with weights $\alpha_i/\sigma_s$  since $\sigma_s = \sum_{i=1}^{s}\alpha_i$. Thus 
	\begin{align*}
		\sigma_s(\xu_s - x_s^*) =\ & \sum_{i=1}^{s}\alpha_i(x_{i-1} - x_s^*) 
		\\
		=\ & \alpha_s(x_{s-1} - x_s^*) + \sum_{i=1}^{s-1}\alpha_i(x_{i-1} - x_{s-1}^*)  + \left(\sum_{i=1}^{s-1}\alpha_i\right)(x_{s-1}^* - x_s^*)
		\\
		=\ & \alpha_s(x_{s-1} - x_s^*) + \sigma_{s-1}(\xu_{s-1} - x_{s-1}^*) + \sigma_{s-1}(x_{s-1}^* - x_{s-1}) + \sigma_{s-1}(x_{s-1} - x_s^*)
		\\
		=\ & \sigma_{s-1}(\xu_{s-1} - x_{s-1}^*) + \sigma_{s-1}(x_{s-1}^* - x_{s-1}) + \sigma_s(x_{s-1} - x_s^*).
	\end{align*}
	The above recursive relation yields
	$
	\sigma_s(\xu_s - x_s^*) = \sum_{i=1}^{s}[\sigma_{i-1}(x_{i-1}^* - x_{i-1}) + \sigma_i(x_{i-1} - x_i^*)].
	$
	By the above equality and our previous result \eqref{eq:dist_subproblem_unconstrained}, we conclude \eqref{eq:dist_xu_xstarsig_unconstrained}.
\qedsymbol\end{proof}

\begin{lem}
	\label{lem:grad_map_properties}
	For any $x, \xu\in\R^n$ and $\eta>0$, $\sigma\ge0$, we have the following properties for the (perturbed) gradient mappings:
	\begin{align}
		\label{eq:xp_lip}
		& \|x^+(\eta+\sigma; x) - x^{++}(\eta, \sigma, \xu; x)\| \le \frac{\sigma}{\eta+\sigma}\|x - \xu\|;
		\\
		\label{eq:xp_monotonicity}
		& \|G_\eta(x)\| \le \|G_{\sigma + \eta}(x)\|.
	\end{align}
	Moreover, if $x^{++}:=x^{++}(\eta, \sigma, \xu; x)$ satisfies 
	\begin{align}
		\label{eq:local_lip}
		f(x^{++}) - f(x) - \langle \nabla f(x), x^{++} - x\rangle \le \frac{M}{2}\|x^{++} - x\|^2
	\end{align}
	for some $M>0$,  we have
	\begin{align}
		\label{eq:3point}
		\begin{aligned}
			&  \left[f(x^{++}) + \phi(x^{++}) + \frac{\sigma}{2}\|x^{++} - \xu\|^2\right] - \left[f(u) + \phi(u) + \frac{\sigma}{2}\|u - \xu\|^2\right]
			\\
			\le\ & \frac{\eta}{2}\|u - x\|^2 - \frac{\sigma + \eta}{2}\|u - x^{++}\|^2 - \frac{\eta-M}{2}\|x^{++} - x\|^2 ,\ \forall u\in X.
		\end{aligned}
	\end{align}
\end{lem}

\begin{proof}
	Let us denote $x^+:=x^+(\eta+\sigma; x)$, $x^{++}:=x^{++}(\eta, \sigma, \xu; x)$ and $x' := x^+(\eta; x)$. By the optimality conditions of \eqref{eq:xp} and \eqref{eq:xpp} we have 
	\begin{align}
		\langle \nabla f(x) + (\eta+\sigma)(x^+ - x), u - x^{+}\rangle + \phi(u) - \phi(x^{+}) \ge 0, \label{eq:oc_simple_1} \\
		\langle \nabla f(x) + \sigma (x^{++}-\bar x) +\eta (x^{++} - x), u - x^{++}\rangle + \phi(u) - \phi(x^{++})\ge 0, \label{eq:oc_simple_2} \\
		\langle \nabla f(x) + \eta (x' - x), u - x'\rangle + \phi(u) - \phi(x') \ge 0 \label{eq:oc_simple_3}
	\end{align}
	for any $u \in X$.
	To prove \eqref{eq:xp_lip}, let us set $u = x^{++}$ in \eqref{eq:oc_simple_1}, $u=\xp$ in \eqref{eq:oc_simple_2}, and add the two relations together. It is easy to see that
	$
	\langle (\eta+\sigma) (x^+ - x^{++})
	+ \sigma (\bar x - x), x^{++} - x^+\rangle  \ge 0 
	$, or equivalently,
	$
	\sigma \langle \bar x - x, x^{++} - x^+\rangle \ge (\eta+\sigma) \|x^+ - x^{++}\|^2,
	$
	which implies \eqref{eq:xp_lip} by the Cauchy-Schwarz inequality.
	Now notice that by definition
	the relation \eqref{eq:xp_monotonicity} is equivalent to $\eta\|x - x'\|\le (\sigma + \eta)\|x - x^{+}\|$.
	Let us set $u = x'$ in \eqref{eq:oc_simple_1}, $u=\xp$ in \eqref{eq:oc_simple_3}, and add the two relations together.
	Then we have 
	$\sigma \langle x^+ - x, x' - x^+\rangle
	- \eta \|x^+ - x'\|^2 \ge 0$,
	which implies 
	$\eta \|x^+ - x'\| \le \sigma \|x - x^+ \|$ again by the Cauchy-Schwarz inequality.
	The previous inequality together with the triangular inequality then immediately implies
	\[
	\eta\|x - x'\| 
	\le \eta (\|x - x^+\|
	+\|x^+ - x'\|) \le (\sigma + \eta) \|x - x^+ \|.
	\]
	In order to show \eqref{eq:3point}, we first notice that
	\eqref{eq:oc_simple_2} is equivalent to 

	\begin{align*}
		\begin{aligned}
			\langle \nabla f(x), x^{++} - u\rangle + \phi(x^{++}) - \phi(u)
			&\le ({\sigma}/{2})(\|u - \xu\|^2 - \|x^{++} - \xu\|^2 - \|u - x^{++}\|^2) \\
			& + ({\eta}/{2})(\|u - x\|^2 - \|x^{++} - x\|^2 - \|u - x^{++}\|^2)
		\end{aligned}
	\end{align*}	
	for any $u\in X$.
	Moreover, from \eqref{eq:local_lip} and the convexity of $f$ we have
	\begin{align*}
		f(\xpp) &\le f(x) + \langle \nabla f(x), \xpp - x\rangle + ({M}/{2})\|\xpp - x\|^2\\
		&\le f(x) + \langle \nabla f(x), u - x\rangle 
		+ \langle \nabla f(x), \xpp - u\rangle
		+({M}/{2})\|\xpp - x\|^2\\
		&\le f(u) + \langle \nabla f(x), \xpp - u\rangle
		+({M}/{2})\|\xpp - x\|^2.
	\end{align*} 
	Combining the above two relations we conclude \eqref{eq:3point}.
\qedsymbol\end{proof}

\begin{lemma}
	\label{thm:Mlemma}
	Suppose that $g:\R^n\to\R$ is a convex smooth function.
	For any $x\in\R^n$, $M>0$, $\eta\ge 2M$, and $\xpp:=x - (1/\eta)\nabla g(x)$,
	if $\xpp$ and $x$ satisfy
	\begin{align}
		\label{eq:M}
		g(\xpp) - g(x) - \langle \nabla g(x), \xpp - x\rangle \le \frac{M}{2}\|\xpp - x\|^2,
	\end{align}
	then we have $\|\nabla g(x)\|\le \sqrt{2}\eta \|x - x^*\|$, where $x^*$ is any minimizer of function $g$.
\end{lemma}

\begin{proof}
	Note that our definition of $\xpp$ is exactly $\xpp(\eta,0,\xu;x)$ described in \eqref{eq:xpp} (with $X\in\R^n$, $\sigma=0$, and $\phi\equiv 0$). Applying result \eqref{eq:3point} in Lemma~\ref{lem:grad_map_properties} and noting that $\eta\ge 2M$ we have
	\begin{align*}
		g(\xpp) - g(u) \le \frac{\eta}{2}\|u - x\|^2 - \frac{\eta}{2}\|u - \xpp\|^2 - \frac{\eta}{4}\|\xpp - x\|^2, \ \forall u\in \R^n.
	\end{align*}
	Letting $u=x^*$ in the above relation, using the optimality of $x^*$ and the fact that $\xpp - x = -(1/\eta)\nabla g(x)$ we conclude that 
	$	\|\nabla g(x)\|^2 \le 2\eta^2\|x^* -x\|^2$.
\qedsymbol\end{proof}

The above lemma allows us to design a backtracking function described in Algorithm~\ref{alg:_searchL}. Applying Lemma~\ref{thm:Mlemma} with $x = x_s$, $x^* = x_s^*$, $g = f_s$, $M=M_s+\sigma_s$, and $\eta = 2(M_s+\sigma_s)$, we conclude that whenever \eqref{eq:M} holds, 
we have $\|\nabla f_s(x_s)\|\le 2\sqrt{2}(M_s+\sigma_s)\|x_s - x_s^*\|$. As a consequence,
\begin{align}
	\label{eq:xs_norm_bound_unconstrained_est}
	\begin{aligned}
		& \|\nabla f(x_s)\| = \|\nabla f_s(x_s) - \sigma_s(x_s - \xu_s)\| 
		=  \|\nabla f_s(x_s) - \sigma_s(x_s - x_s^*) - \sigma_s(\xu_s-x_s^*)\| 
		\\
		\le &  (2\sqrt{2}M_s+(2\sqrt{2}+1)\sigma_s)\|x_s - x_s^*\| + \sigma_s\|x_s^* - \xu_s\|,
	\end{aligned}
\end{align}
which is analogous to the gradient-to-distance relation \eqref{eq:xs_norm_bound_unconstrained} but with $L$ replaced by $M_s$.
Apparently, we can apply one single gradient descent step with backtracking, i.e., Algorithm~\ref{alg:_searchL} with input $g=f_s$, $\sigma =\sigma_s$, $x= x_s$ and initial guess $M_0$, to estimate the local Lipschitz constant $M_s$.


\begin{theorem}
	\label{thm:conv_proposed_unconstrained_searchL} 
		For any input argument $M_0, \sigma_1>0$, the AR method outputs an $\hat x$ with $\|\nabla f(\hat x)\|\le 5\sigma_1\operatorname{dist}(x_0, X^*)$ within $4 + 3\sqrt{\max\{M_0/2, 2L\}/\sigma_1}+16\sqrt{2c_\cA }\sqrt{L/\sigma_1}$ gradient evaluations of $\nabla f$.
		Specially, if $M_0\le 4L$, the total number of gradient evaluations is bounded by $4 + C_1\sqrt{L/\sigma_1}$, where $C_1:= \sqrt{2}(3 + 16\sqrt{2c_\cA})$ is a universal constant. 
		If in addition $\sigma_1 = \varepsilon/(5D)$ for some $D>0$, then an approximate solution $\hat x$ satisfying $\|\nabla f(\hat x)\|\le \varepsilon\operatorname{dist}(x_0, X^*)/D$  can be computed within at most  $4 + \sqrt{5}C_1\sqrt{LD/\varepsilon}$ gradient evaluations of $\nabla f$. 
	\end{theorem}

\begin{proof}
		First note that by \eqref{eq:dist_xu_xstarsig_unconstrained} in Proposition~\ref{pro:xstar_dist_shrink_unconstrained} and the relation in \eqref{eq:xs_norm_bound_unconstrained_est}, we have 
		\begin{align}
			\label{eq:gradS_estimate_unconstrained_searchL}
			\begin{aligned}
				\|\nabla f(x_s)\|
				&	\le (2\sqrt{2}M_s + (1+2\sqrt{2})\sigma_s)\|x_s -x_s^*\| \\
				&\quad + \sigma_1\|x^* - x_0\| + \sum_{i=2}^s(\sigma_{i-1} + \sigma_i)\|x_{i-1}^* - x_{i-1}\|,
			\end{aligned}
		\end{align}
		which is analogous to \eqref{eq:gradS_estimate_unconstrained}.
		Consider the call to the subroutine $\cA$ for minimizing $f_s(x)$ in \eqref{eq:subproblem_unconstrained_searchL}. Noting that $f_s$ is $\sigma_s$-strongly convex, we have $\|x - x_s^*\|^2 \le ({2}/{\sigma_s})(f_s(x) - f_s(x_s^*)),\ \forall x\in\R^n$. In view of this observation and Assumption~\ref{assum:A_unconstrained_searchL}, after the $k$-th gradient evaluation of $\nabla f$, subroutine $\cA$ will compute an approximation solution $x_s^k$ such that
		\begin{align}
			\label{eq:A_dist_shrink}
			\|x_s^k - x_s^*\|\le\dfrac{1}{k}\sqrt{\dfrac{2L_s^k}{\sigma_s}}\|x_{s-1} - x_{s}^*\|\le  \dfrac{1}{k}\sqrt{\dfrac{2c_\cA L}{\sigma_s}}\|x_{s-1} - x_{s}^*\|.
		\end{align}
		Also by	Assumption~\ref{assum:A_unconstrained_searchL}, the number of gradient evaluations that $\cA$ performs is bounded by 
		\begin{align}
			\label{eq:Ns}
			N_s:=\lceil8\sqrt{2L_s/\sigma_s}\rceil\le \lceil8\sqrt{2c_\cA L/\sigma_s}\rceil.
		\end{align} 
		By the above two relations and \eqref{eq:dist_subproblem_unconstrained} in  
		Proposition~\ref{pro:xstar_dist_shrink_unconstrained}, the output solution $x_s$ computed at the termination of subroutine $\cA$ applied to minimize $f_s$ satisfies
		\begin{align*}
			\|x_s - x_s^*\| \le \frac{1}{8}\|x_{s-1} - x_s^*\| \le \frac{1}{8}\|x_{s-1} - x_{s-1}^*\|,\ \forall s = 1,\ldots, S.
		\end{align*}
		Using the above result and the fact that $\sigma_s = 4\sigma_{s-1}$ for all $s>1$ in our previous estimate of $\|\nabla f(x_s)\|$ in  \eqref{eq:gradS_estimate_unconstrained_searchL}, we have
		\begin{align}
			\label{eq:tmp_grad_est}
			\begin{aligned}
				\|\nabla f(x_s)\| \le\ & (2\sqrt{2}M_s + (1+2\sqrt{2})\sigma_s)8^{-s}\|x^* - x_0\|  
				\\
				&\ + \sigma_1\|x^* - x_0\| + \sum_{i=2}^{s}5\cdot 4^{i-2}\sigma_1 8^{-i+1}\|x^* - x_0\|
				\\
				\le\ & (\sqrt{2}M_s + (1/2+\sqrt{2})\sigma_s) 4^{-s}\|x_0 - x^*\| + (9/4)\sigma_1\|x_0 - x^*\|.
			\end{aligned}
		\end{align}
		Here $x^*$ is any solution in the optimal solution set $X^*$. 

		We will now estimate $\sigma_s$ and $4^{-s}$ in the above relation when the termination criterion $\sigma_s\ge M_s$ is satisfied. 
		If the criterion is satisfied when $s=1$, by \eqref{eq:tmp_grad_est} the output $\hat x=x_1$ satisfies
		\begin{align*}
			\|\nabla f(\hat x)\| \le (1/2+2\sqrt{2})\sigma_1 4^{-1}\|x_0 - x^*\| + (9/4)\sigma_1\|x_0 - x^*\|\le 5\sigma_1\|x_0 - x^*\|.
		\end{align*}
		Otherwise, let $S>1$ be the smallest $s$ when the termination criterion $\sigma_s\ge M_s$ is satisfied. Observe in the backtracking function that $M_s\le\max\{M_{s-1}/2, 2L\}$. Thus we have $M_s\le \max\{M_0/2, 2L\}$ for $s=1,\ldots, S$. Use this observation and recalling that $\sigma_s = 4\sigma_{s-1}$, we have 
		\begin{align}
			\label{eq:sigmaS_bound}
			M_S\le 4^{S-1}\sigma_1 = \sigma_{S} = 4\sigma_{S-1}<4M_{S-1}\le \max\{2M_0, 8L\}.
		\end{align}
		Thus by \eqref{eq:tmp_grad_est}, during termination the output $\hat x = x_S$ satisfies
		\begin{align*}
			\|\nabla f(\hat x)\| \le & (1/2+2\sqrt{2})\sigma_S 4^{-S}\|x_0 - x^*\| + (9/4)\sigma_1\|x_0 - x^*\|
			\le 5\sigma_1\|x_0 - x^*\|.
		\end{align*}
		Since $x^*$ here is an arbitrary optimal solution, we have $\|\nabla f(\hat x)\|\le 5\sigma_1\operatorname{dist}(x_0, X^*)$.	

		Next we will bound the total number of gradient estimations. 
		If the termination criterion is satisfied when $s=1$,  bounding the numbers of gradient evaluations required for backtracking line-search and subroutine $\cA$ respectively, we have the bound $1 + N_1$. Recalling the value of $N_s$ and its bound in \eqref{eq:Ns}, this number is bounded by $ 1 + 8\sqrt{2c_A L/\sigma_1}$. If the termination criterion is satisfied at some $s=S>1$,  the total number of gradient evaluations is $S+\sum_{s=1}^{S}N_s$. Here by \eqref{eq:sigmaS_bound} we have $S\le 2 + \log_4(\max\{M_0/2, 2L\}/\sigma_1)$. Also, recalling the value of $N_s$ and its bound in \eqref{eq:Ns} and noting that $\sigma_s = 4\sigma_{s-1}$ for all $s$ we have
		\begin{align*}
			\sum_{s=1}^{S}N_s \le \sum_{s=1}^{S}1 + 8\sqrt{2c_\cA L/\sigma_s} \le & S + 8\sqrt{2c_\cA L/\sigma_1}\sum_{s=1}^{\infty}2^{-(s-1)}  \le S + 16\sqrt{2c_\cA L/\sigma_1}.
		\end{align*}      
		Summarizing the above we can bound the total number of gradient evaluations by
		\begin{align}
			\label{eq:total_gradient}
			\begin{aligned}
				& S+\sum_{s=1}^{S}N_s 
				\le 2S + 16\sqrt{2c_\cA L/\sigma_1} \le 2(2 + \log_4(\max\{M_0/2, 2L\}/\sigma_1)) + 16\sqrt{2c_\cA L/\sigma_1}
				\\ 
				\le\ & 4 + 3\sqrt{\max\{M_0/2, 2L\}/\sigma_1}+16\sqrt{2c_\cA }\sqrt{L/\sigma_1}. 
			\end{aligned}
		\end{align}
		Here in the last inequality we use the fact that $2\log_4 t \cmo{<} 3\sqrt{t}$ for all $t>0$.
		Note that the above bound is also an upper bound of number of gradient evaluations if the termination criterion is satisfied when $s=1$. 
		The remainder parts of result then immediately follows from \eqref{eq:total_gradient}.
	\qedsymbol\end{proof}

\begin{proof}
		We start with three observations. First, by Theorem~\ref{thm:conv_proposed_unconstrained_searchL}, 
		the output $y_{t}$ of the AR method satisfies $\|\nabla f(y_{t})\|\le \mu_{t-1}\|y_{t-1}-x^*\|/2$ and the total number of gradient evaluations for computing $y_t$ is bounded by
		$4 +  C_1\sqrt{10L/\mu_{t-1}}$.
		Second, using the previous observation and 
		the relation 
  \begin{equation}\label{eq:growth}
  \|y_{t-1}-x^*\|\le \tfrac{1}{\mu}\|\nabla f(y_{t-1})\|
  \end{equation}
  due to the strong convexity of $f$, we conclude that $\|\nabla f(y_{t})\|\le \|\nabla f(y_{t-1})\|/2$  and hence that $\mu_t$ will no longer change whenever $\mu_{t-1}\le \mu$. Therefore $\mu_t\ge \mu/4$ for all $t$.
		Third, the algorithm will terminate with $\|\nabla f(y_t)\|\le \varepsilon$ whenever $t\ge P:=\lceil\log_4(\mu_0/\mu)\rceil + \lceil\log_2(\|\nabla f(y_0)\|/\varepsilon)\rceil$. Here $P$ is the sum of two parts: $\lceil\log_4(\mu_0/\mu)\rceil$ counts the number of times when $\|\nabla f(y_t)\|>\|\nabla f(y_{t-1})\|/2$ and the value of $\mu_t$ is reduced from $\mu_{t-1}$; $\lceil\log_2(\|\nabla f(y_0)\|/\varepsilon)\rceil$ counts the number of times when $\|\nabla f(y_t)\|\le\|\nabla f(y_{t-1})\|/2$. Summarizing the above observations, the total number of gradient evaluations $N$ is bounded by
		\begin{align*}
			N \le\ & 4P + C_1P\sqrt{40L/\mu} \le (4+8\sqrt{5}C_1)P\sqrt{L/\mu}
			\\
			\le\ & (4+8\sqrt{5}C_1)\lceil\log_4(\mu_0/\mu)\rceil\sqrt{L/\mu}  + (4+8\sqrt{5}C_1)\sqrt{L/\mu}\lceil\log_2(\|\nabla f(y_0)\|/\varepsilon)\rceil.
		\end{align*}

	\cmo{
		We may also analyze the total number of gradient evaluations from an alternative perspective when we know that  $\mu_0\le 2^{j}\varepsilon/\operatorname{dist}(y_0,X^*)$. By   Theorem~\ref{thm:conv_proposed_unconstrained_searchL}, the first AR call is guaranteed to yield $y_1$ such that $\|\nabla f(y_1)\| \le 2^{j-1}\varepsilon$. If $j\le 1$, then $y_1$ already satisfies $\|\nabla f(y_1)\|\le\varepsilon$. If $j>1$,
		then after $(j-1)$ occurrences of $\|\nabla f(y_t)\| \le \|\nabla f(y_{t-1})\|/2$ we will have $\|\nabla f(y_t)\|\le \varepsilon$. Therefore, the algorithm will terminate with $\|\nabla f(y_t)\|\le \varepsilon$ whenever $t\ge P:=\lceil\log_4(\mu_0/\mu)\rceil + j$ and we can bound $N$ by $N \le (4+8\sqrt{5}C_1)P\sqrt{L/\mu}$ similar as the proof of the previous bound.
	}	

	\qedsymbol
	\end{proof}

