		\begin{align}
			\label{eq:gradS_estimate_unconstrained_searchL}
			\begin{aligned}
				\|\nabla f(x_s)\|
				&	\le (2\sqrt{2}M_s + (1+2\sqrt{2})\sigma_s)\|x_s -x_s^*\| \\
				&\quad + \sigma_1\|x^* - x_0\| + \sum_{i=2}^s(\sigma_{i-1} + \sigma_i)\|x_{i-1}^* - x_{i-1}\|,
			\end{aligned}
		\end{align}
		which is analogous to \eqref{eq:gradS_estimate_unconstrained}.
		Consider the call to the subroutine $\cA$ for minimizing $f_s(x)$ in \eqref{eq:subproblem_unconstrained_searchL}. Noting that $f_s$ is $\sigma_s$-strongly convex, we have $\|x - x_s^*\|^2 \le ({2}/{\sigma_s})(f_s(x) - f_s(x_s^*)),\ \forall x\in\R^n$. In view of this observation and Assumption~\ref{assum:A_unconstrained_searchL}, after the $k$-th gradient evaluation of $\nabla f$, subroutine $\cA$ will compute an approximation solution $x_s^k$ such that
		\begin{align}
			\label{eq:A_dist_shrink}
			\|x_s^k - x_s^*\|\le\dfrac{1}{k}\sqrt{\dfrac{2L_s^k}{\sigma_s}}\|x_{s-1} - x_{s}^*\|\le  \dfrac{1}{k}\sqrt{\dfrac{2c_\cA L}{\sigma_s}}\|x_{s-1} - x_{s}^*\|.
		\end{align}
		Also by	Assumption~\ref{assum:A_unconstrained_searchL}, the number of gradient evaluations that $\cA$ performs is bounded by 
		\begin{align}
			\label{eq:Ns}
			N_s:=\lceil8\sqrt{2L_s/\sigma_s}\rceil\le \lceil8\sqrt{2c_\cA L/\sigma_s}\rceil.
		\end{align} 
		By the above two relations and \eqref{eq:dist_subproblem_unconstrained} in  
		Proposition~\ref{pro:xstar_dist_shrink_unconstrained}, the output solution $x_s$ computed at the termination of subroutine $\cA$ applied to minimize $f_s$ satisfies
		\begin{align*}
			\|x_s - x_s^*\| \le \frac{1}{8}\|x_{s-1} - x_s^*\| \le \frac{1}{8}\|x_{s-1} - x_{s-1}^*\|,\ \forall s = 1,\ldots, S.
		\end{align*}
		Using the above result and the fact that $\sigma_s = 4\sigma_{s-1}$ for all $s>1$ in our previous estimate of $\|\nabla f(x_s)\|$ in  \eqref{eq:gradS_estimate_unconstrained_searchL}, we have
		\begin{align}
			\label{eq:tmp_grad_est}
			\begin{aligned}
				\|\nabla f(x_s)\| \le\ & (2\sqrt{2}M_s + (1+2\sqrt{2})\sigma_s)8^{-s}\|x^* - x_0\|  
				\\
				&\ + \sigma_1\|x^* - x_0\| + \sum_{i=2}^{s}5\cdot 4^{i-2}\sigma_1 8^{-i+1}\|x^* - x_0\|
				\\
				\le\ & (\sqrt{2}M_s + (1/2+\sqrt{2})\sigma_s) 4^{-s}\|x_0 - x^*\| + (9/4)\sigma_1\|x_0 - x^*\|.
			\end{aligned}
		\end{align}
		Here $x^*$ is any solution in the optimal solution set $X^*$. 

		We will now estimate $\sigma_s$ and $4^{-s}$ in the above relation when the termination criterion $\sigma_s\ge M_s$ is satisfied. 
		If the criterion is satisfied when $s=1$, by \eqref{eq:tmp_grad_est} the output $\hat x=x_1$ satisfies
		\begin{align*}
			\|\nabla f(\hat x)\| \le (1/2+2\sqrt{2})\sigma_1 4^{-1}\|x_0 - x^*\| + (9/4)\sigma_1\|x_0 - x^*\|\le 5\sigma_1\|x_0 - x^*\|.
		\end{align*}
		Otherwise, let $S>1$ be the smallest $s$ when the termination criterion $\sigma_s\ge M_s$ is satisfied. Observe in the backtracking function that $M_s\le\max\{M_{s-1}/2, 2L\}$. Thus we have $M_s\le \max\{M_0/2, 2L\}$ for $s=1,\ldots, S$. Use this observation and recalling that $\sigma_s = 4\sigma_{s-1}$, we have 
		\begin{align}
			\label{eq:sigmaS_bound}
			M_S\le 4^{S-1}\sigma_1 = \sigma_{S} = 4\sigma_{S-1}<4M_{S-1}\le \max\{2M_0, 8L\}.
		\end{align}
