\begin{proof}
		We start with three observations. First, by Theorem~\ref{thm:conv_proposed_unconstrained_searchL}, 
		the output $y_{t}$ of the AR method satisfies $\|\nabla f(y_{t})\|\le \mu_{t-1}\|y_{t-1}-x^*\|/2$ and the total number of gradient evaluations for computing $y_t$ is bounded by
		$4 +  C_1\sqrt{10L/\mu_{t-1}}$.
		Second, using the previous observation and 
		the relation 
  \begin{equation}\label{eq:growth}
  \|y_{t-1}-x^*\|\le \tfrac{1}{\mu}\|\nabla f(y_{t-1})\|
  \end{equation}
  due to the strong convexity of $f$, we conclude that $\|\nabla f(y_{t})\|\le \|\nabla f(y_{t-1})\|/2$  and hence that $\mu_t$ will no longer change whenever $\mu_{t-1}\le \mu$. Therefore $\mu_t\ge \mu/4$ for all $t$.
		Third, the algorithm will terminate with $\|\nabla f(y_t)\|\le \varepsilon$ whenever $t\ge P:=\lceil\log_4(\mu_0/\mu)\rceil + \lceil\log_2(\|\nabla f(y_0)\|/\varepsilon)\rceil$. Here $P$ is the sum of two parts: $\lceil\log_4(\mu_0/\mu)\rceil$ counts the number of times when $\|\nabla f(y_t)\|>\|\nabla f(y_{t-1})\|/2$ and the value of $\mu_t$ is reduced from $\mu_{t-1}$; $\lceil\log_2(\|\nabla f(y_0)\|/\varepsilon)\rceil$ counts the number of times when $\|\nabla f(y_t)\|\le\|\nabla f(y_{t-1})\|/2$. Summarizing the above observations, the total number of gradient evaluations $N$ is bounded by
		\begin{align*}
			N \le\ & 4P + C_1P\sqrt{40L/\mu} \le (4+8\sqrt{5}C_1)P\sqrt{L/\mu}
			\\
			\le\ & (4+8\sqrt{5}C_1)\lceil\log_4(\mu_0/\mu)\rceil\sqrt{L/\mu}  + (4+8\sqrt{5}C_1)\sqrt{L/\mu}\lceil\log_2(\|\nabla f(y_0)\|/\varepsilon)\rceil.
		\end{align*}

	\cmo{
		We may also analyze the total number of gradient evaluations from an alternative perspective when we know that  $\mu_0\le 2^{j}\varepsilon/\operatorname{dist}(y_0,X^*)$. By   Theorem~\ref{thm:conv_proposed_unconstrained_searchL}, the first AR call is guaranteed to yield $y_1$ such that $\|\nabla f(y_1)\| \le 2^{j-1}\varepsilon$. If $j\le 1$, then $y_1$ already satisfies $\|\nabla f(y_1)\|\le\varepsilon$. If $j>1$,
		then after $(j-1)$ occurrences of $\|\nabla f(y_t)\| \le \|\nabla f(y_{t-1})\|/2$ we will have $\|\nabla f(y_t)\|\le \varepsilon$. Therefore, the algorithm will terminate with $\|\nabla f(y_t)\|\le \varepsilon$ whenever $t\ge P:=\lceil\log_4(\mu_0/\mu)\rceil + j$ and we can bound $N$ by $N \le (4+8\sqrt{5}C_1)P\sqrt{L/\mu}$ similar as the proof of the previous bound.
	}	

	\qedsymbol
	\end{proof}

