	With the selection of $\gamma_s = 1 - \sigma_{s-1}/\sigma_s$ in the definition of prox-center $\xu_s$ in   \eqref{eq:xus_unconstrained}, the subproblem \eqref{eq:subproblem_unconstrained} is equivalent to
	\begin{align*}
		x_s^* = \argmin_{x\in \R^n} f(x) + \dfrac{\sigma_{s-1}}{2}\|x - \xu_{s-1}\|^2 + \dfrac{\sigma_s - \sigma_{s-1}}{2}\|x - x_{s-1}\|^2,\ \forall s \ge 1.
	\end{align*}

\begin{lemma}
	\label{thm:Mlemma}
	Suppose that $g:\R^n\to\R$ is a convex smooth function.
	For any $x\in\R^n$, $M>0$, $\eta\ge 2M$, and $\xpp:=x - (1/\eta)\nabla g(x)$,
	if $\xpp$ and $x$ satisfy
	\begin{align}
		\label{eq:M}
		g(\xpp) - g(x) - \langle \nabla g(x), \xpp - x\rangle \le \frac{M}{2}\|\xpp - x\|^2,
	\end{align}
	then we have $\|\nabla g(x)\|\le \sqrt{2}\eta \|x - x^*\|$, where $x^*$ is any minimizer of function $g$.
\end{lemma}

\begin{proof}
	Note that our definition of $\xpp$ is exactly $\xpp(\eta,0,\xu;x)$ described in \eqref{eq:xpp} (with $X\in\R^n$, $\sigma=0$, and $\phi\equiv 0$). Applying result \eqref{eq:3point} in Lemma~\ref{lem:grad_map_properties} and noting that $\eta\ge 2M$ we have
	\begin{align*}
		g(\xpp) - g(u) \le \frac{\eta}{2}\|u - x\|^2 - \frac{\eta}{2}\|u - \xpp\|^2 - \frac{\eta}{4}\|\xpp - x\|^2, \ \forall u\in \R^n.
	\end{align*}
	Letting $u=x^*$ in the above relation, using the optimality of $x^*$ and the fact that $\xpp - x = -(1/\eta)\nabla g(x)$ we conclude that 
	$	\|\nabla g(x)\|^2 \le 2\eta^2\|x^* -x\|^2$.
\qedsymbol\end{proof}

