The basic problem of interest in this paper is to compute an
approximate stationary point $\hat x$ to  
the unconstrained optimization problem
\begin{equation} \label{eq:basic_problem}
	f^* = \min_{x\in\R^n}f(x),
\end{equation}

\begin{algorithm}[h]
	\caption{\label{alg:proposed_unconstrained} An accumulative regularization method for gradient minimization}
	\begin{algorithmic}
		\Require Total number of subproblems $S$, strictly increasing regularization parameters $\{\sigma_s\}_{s=0}^{S}$ with $\sigma_0=0$, and initial point $x_0\in\R^n$. \State Set initial prox-center to $\xu_0 := x_0$.
		\For {$s=1,\ldots, S$}
		\State Set
		\begin{align}
			\label{eq:xus_unconstrained}
			\xu_s = (1-\gamma_s) \xu_{s-1} + \gamma_s x_{s-1}\text{ with }\gamma_s =1 - \sigma_{s-1}/\sigma_s.
		\end{align}
		\State Compute an approximate solution $x_s$ of the proximal mapping subproblem
		\begin{align}
			\label{eq:subproblem_unconstrained}
			x_s^*:=\argmin_{x\in \R^n} \{f_s(x):=f(x) + \frac{\sigma_s}{2}\|x - \xu_s\|^2\}
		\end{align}
		by running subroutine $\cA(f, \sigma_s, \xu_s, x_{s-1}, N_s)$ with $N_s$ gradient evaluations of $\nabla f$ and initial point $x_{s-1}$.
		\EndFor
		\State Output $x_S$.
	\end{algorithmic}
\end{algorithm}

In this section, we show that the accumulative regularization technique we introduce in the previous section can be adapted to problems with constrained feasible sets, and (nested) composite objective function. We consider the problem with simple feasible set $X$ and composite function $\phi$:
\begin{align}
	\label{eq:problem} \min_{x\in X}\{ F(x):=f(x) + \phi(x)\}.
\end{align}

\begin{align}
	\label{eq:xpp}
	x^{++}(\eta, \sigma, \xu; x):=\argmin_{u\in X}\langle \nabla f(x), u\rangle + \phi(u) + \frac{\sigma}{2}\|u - \xu\|^2 + \frac{\eta}{2}\|u - x\|^2.
\end{align}

Clearly, $x^*$ is an optimal solution of \eqref{eq:problem} if and only if the \emph{projected gradient} $G_\eta(x^*) = 0$ for some $\eta>0$, where
\begin{align}
	\label{eq:G}
	G_{\eta}(x) :=\ & \eta(x - x^+(\eta;x))\text{ and }
	\\
	\label{eq:xp}
	x^+(\eta;x):=\ &x^{++}(\eta, 0, x;x) = \argmin_{u\in X}\langle\nabla f(x), u\rangle + \phi(u) + \frac{\eta}{2}\|u - x\|^2\ \forall x\in \R^n.
\end{align}

\begin{algorithm*}[h] 
	\caption{$M$=Backtracking($g$, $\sigma$, $x$, $M_0$) \label{alg:_searchL}}
	\begin{algorithmic}
		\For{$j=0,1,\ldots,$}
		\State Set
		$			\xpp = x - ({1}/{(2(M_j + \sigma))})\nabla g(x).
		$
		\State If 
		\begin{align}
			\label{eq:linesearch_estL_success_criterion}
			g(\xpp) - g(x) - \langle \nabla g(x), \xpp - x\rangle \le ({(M_j + \sigma)}/{2})\|\xpp - x\|^2, 
		\end{align}
		then {\bf terminate} with $M=M_j$. Otherwise, set $M_{j+1} = 2M_{j}$. 
		\EndFor
	\end{algorithmic}
\end{algorithm*}

\begin{algorithm}[!h]
	\caption{\label{alg:proposed_unconstrained_searchL} Accumulative regularization (AR) without the knowledge of $L$}
	\begin{algorithmic}
		\Function{$(\hat x, M)=\ $AR}{$f, x_0, \sigma_1, M_0$}
		\State Set the initial prox-center $\xu_0 = x_0$, and denote $\sigma_0=0$.
		\For {$s=1,2,\ldots$}
		\State If $s>1$, then set $\sigma_s=4\sigma_{s-1}$.
		\State Set $\xu_s =  (1-\gamma_s) \xu_{s-1} + \gamma_s x_{s-1}$ with $\gamma_s=1 - \sigma_{s-1}/\sigma_s$.

		\State Compute an approximate solution $x_s\in \R^n$ of
		\begin{align}
			\label{eq:subproblem_unconstrained_searchL}
			x_s^*:=\argmin_{x\in \R^n} \{ f_s(x):=f(x) + \dfrac{\sigma_s}{2}\|x - \xu_s\|^2\}
		\end{align}
		by running subroutine $x_s = \cA(f, \sigma_s, \xu_s, x_{s-1})$ with initial point $x_{s-1}$. 

		\State Set $M_s=$ Backtracking ($f_s$, $\sigma_s$, $x_s$, $M_{s-1}/2$).
		\State If $\sigma_s\ge M_s$, then {\bf terminate} with $\hat x=x_s$ and $M=M_s$ . 
		\EndFor
		\EndFunction
	\end{algorithmic}
\end{algorithm}

\begin{assumption}
	\label{assum:A_unconstrained_searchL}
	The subroutine $x_s =\cA(f, \sigma_s, \xu_s, x_{s-1})$ has the following performance guarantees after the $k$-th gradient evaluation of $\nabla f$:
	\begin{align}
		\label{eq:A_cond_unconstrained_searchL}
		f_s(x_s^k) - f_s(x_s^*) \le ({L_s^k}/{k^2})\|x_{s-1} - x_s^*\|^2.
	\end{align} 
	Here $x_s^k$ is the computed approximate solution and $L_s^k$ is an estimate of Lipschitz constant $L$ such that $L_s^k\le c_\cA L$, where $c_\cA$ is a universal constant that depends on algorithm $\cA$. 
	Subroutine $\cA$ will terminate whenever $k\ge 8\sqrt{2L_s^k/\sigma_s}$ and output the approximate solution $x_s = x_s^k$.
\end{assumption}

\begin{algorithm}[h]
		\caption{\label{alg:proposed_SCAR_noflag} A parameter-free strongly convex accumulative regularization (SCAR) algorithm}
		\begin{algorithmic}
			\Function{($\hat x$, $\hat M$) = SCAR}{$f$, $\varepsilon$, $y_0$, $\mu_0$, $M_0$}
			\For {$t=1,2,\ldots$}
			\State Set
			$
			(y_{t},M_{t}) = \text{AR}(f, y_{t-1}, \mu_{t-1}/10, M_{t-1})
			$ (see Algorithm~\ref{alg:proposed_unconstrained_searchL}).
			\State If {$\|\nabla f(y_t)\|>\|\nabla f(y_{t-1})\|/2$}, then set $\mu_t = \mu_{t-1}/4$ and $y_t = y_{t-1}$. 		
			\State If $\|\nabla f(y_{t})\|\le \varepsilon$, then \textbf{terminate} with $\hat x = y_{t}$ and $\hat M = M_t$.\EndFor
			\EndFunction
		\end{algorithmic}
	\end{algorithm}
